    const state = window;
    state.sentControls = [];
    state.sentBytes = 0;
    state.sourceReads = 0;
    const originalSend = RTCDataChannel.prototype.send;
    RTCDataChannel.prototype.send = function (data) {
      if (typeof data === "string") state.sentControls.push(JSON.parse(data));else state.sentBytes += data instanceof Blob ? data.size : data.byteLength;
      return Reflect.apply(originalSend, this, [data]);
    };
