      lastModified: 7
    });
    const slice = file.slice.bind(file);
    file.slice = (...args) => {
      state.sourceReads += 1;
      return slice(...args);
    };
    state.showDirectoryPicker = async () => ({
      kind: "directory",
      name: "browser-fixture",
      async *entries() {
        yield [file.name, {
          kind: "file",
          name: file.name,
          getFile: async () => file
        }];
      }
    });
