      const handle = await directory.getFileHandle("test.bin", {
        create: true
      });
      if (!reuseSource) {
        const writer = await handle.createWritable();
        await writer.write(new Uint8Array(fileBytes).fill(37));
        await writer.close();
      }
      return directory;
    };
    window.showOpenFilePicker = async () => {
      const directory = await state.showDirectoryPicker();
      const empty = await directory.getFileHandle("empty.bin", {
        create: true
      });
      const writer = await empty.createWritable();
      await writer.close();
      return [await directory.getFileHandle("test.bin"), empty];
    };
