      const directory = (name, entries) => ({
        kind: "directory",
        name,
        async *entries() {
          yield* entries;
        }
      });
      const groups = [];
      for (let group = 0; group < 12; group++) {
        const entries = [];
        for (let offset = 0; offset < 100; offset++) {
